func pathSum(root *TreeNode, targetSum int) int {
    prefixCount := map[int64]int{0: 1} // 空路径前缀和为 0
    var res int
    var dfs func(*TreeNode, int64)
    dfs = func(node *TreeNode, curSum int64) {
        if node == nil {
            return
        }
        curSum += int64(node.Val)
        res += prefixCount[curSum-int64(targetSum)]
        prefixCount[curSum]++
        dfs(node.Left, curSum)
        dfs(node.Right, curSum)
        // 回溯：离开当前节点，撤销前缀和
        prefixCount[curSum]--
    }
    dfs(root, 0)
    return res
}
